AModelViewerPanel viewer;
viewer.Init();
workspace.RegisterPanel(&viewer);    // AEditorPanel として登録

// CAssetBrowser からの選択通知で自動 LoadModelAsset:
workspace.BroadcastAssetSelected("models/hero.mdl");

if (viewer.HasModel()) {
    auto& cam = viewer.Camera();      // renderer が ViewMatrix を取り出す
    (void)cam;
}
